// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= type(uint256).max / 2);
        address user = address(0x1234);
        vm.deal(user, amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(user);
        c.deposit{value: amount}();
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
